import { ref } from 'vue'
</script>

<template>
  <div class="w-full h-full flex flex-col items-center justify-center bg-gradient-to-b from-base-200 to-base-100 p-8">
    <!-- Logo and Introduction Section -->
    <div class="text-center mb-12 max-w-2xl">
